import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    Color,
    Vector3,
    Euler,
    AmbientLight,
    PointLight,
    Object3D
  } = THREE;

  const root = new Group();
  root.name = config.id || config.type || 'stat-tile';
  root.userData = root.userData || {};

  const timelines = [];
  const primitiveResults = [];
  const disposables = [];
  let disposed = false;
  let loadedScene = null;

  const colors = config.intent?.visualSpec?.colors || {};
  const ink = colors.ink || '#16161d';
  const paper = colors.paper || '#e8ecf2';
  const accent = colors.accent || '#ff2a38';
  const surface = colors.surface || '#0b0b10';

  const makeStandardMaterial = (color, options = {}) => {
    const material = new MeshStandardNodeMaterial();
    material.color = new Color(color);
    material.roughness = options.roughness ?? 0.62;
    material.metalness = options.metalness ?? 0.42;
    material.clearcoat = options.clearcoat ?? 0.16;
    material.clearcoatRoughness = 0.5;
    disposables.push(material);
    return material;
  };

  const stage = new Group();
  stage.name = 'stat-tile-stage';
  root.add(stage);

  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    vec3(new Color(surface).r, new Color(surface).g, new Color(surface).b),
    vec3(new Color(ink).r, new Color(ink).g, new Color(ink).b),
    uv().y
  );
  disposables.push(backdropMaterial);

  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMaterial);
  backdrop.name = 'vertical-engineered-backdrop';
  backdrop.position.set(0, 0, -2.5);
  stage.add(backdrop);
  disposables.push(backdrop.geometry);

  const fill = new AmbientLight(paper, 0.34);
  fill.name = 'paper-fill';
  stage.add(fill);

  const rim = new PointLight(accent, 0.72, 5.5, 2);
  rim.name = 'signal-red-rim';
  rim.position.set(1.7, 1.7, 1.6);
  stage.add(rim);

  const key = new PointLight(paper, 0.86, 6, 2);
  key.name = 'machined-surface-key';
  key.position.set(-2.2, 2.6, 3.2);
  stage.add(key);

  const contactMaterial = new MeshBasicNodeMaterial();
  contactMaterial.color = new Color('#050509');
  contactMaterial.transparent = true;
  contactMaterial.opacity = 0.48;
  disposables.push(contactMaterial);

  const contactShadow = new Mesh(
    new THREE.CircleGeometry(1.35, 48),
    contactMaterial
  );
  contactShadow.name = 'radial-contact-shadow';
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, -0.78, -0.72);
  contactShadow.scale.set(1.15, 0.58, 1);
  stage.add(contactShadow);
  disposables.push(contactShadow.geometry);

  const cardGroup = new Group();
  cardGroup.name = 'machined-stat-card';
  stage.add(cardGroup);

  const cardMaterial = makeStandardMaterial(surface, {
    roughness: 0.58,
    metalness: 0.5,
    clearcoat: 0.2
  });

  const card = new Mesh(new BoxGeometry(2.15, 1.28, 0.16), cardMaterial);
  card.name = 'machined-card-surface';
  card.position.z = -0.04;
  cardGroup.add(card);
  disposables.push(card.geometry);

  const edgeMaterial = makeStandardMaterial(accent, {
    roughness: 0.52,
    metalness: 0.28,
    clearcoat: 0.18
  });

  const edge = new Mesh(new BoxGeometry(2.22, 0.045, 0.2), edgeMaterial);
  edge.name = 'accent-focus-edge';
  edge.position.set(0, 0.64, 0.05);
  cardGroup.add(edge);
  disposables.push(edge.geometry);

  const innerMaterial = makeStandardMaterial(ink, {
    roughness: 0.7,
    metalness: 0.34,
    clearcoat: 0.12
  });

  const innerPlate = new Mesh(new BoxGeometry(1.84, 0.98, 0.035), innerMaterial);
  innerPlate.name = 'recessed-stat-plate';
  innerPlate.position.set(0, -0.02, 0.065);
  cardGroup.add(innerPlate);
  disposables.push(innerPlate.geometry);

  const accentPin = new Mesh(
    new THREE.CylinderGeometry(0.055, 0.055, 0.12, 20),
    edgeMaterial
  );
  accentPin.name = 'signal-accent-pin';
  accentPin.rotation.z = Math.PI / 2;
  accentPin.position.set(-0.78, 0.37, 0.12);
  cardGroup.add(accentPin);
  disposables.push(accentPin.geometry);

  const meshGroup = new Group();
  meshGroup.name = 'gear-a-asset';
  meshGroup.position.set(0, 0, 0.18);
  meshGroup.scale.setScalar(0.72);
  cardGroup.add(meshGroup);

  const loadAsset = () => {
    if (!config.meshUrl || !ctx.glbLoader?.loadGLB) return;

    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (disposed || !gltf?.scene) return;

      loadedScene = gltf.scene;
      loadedScene.name = 'gear-a-loaded-mesh';
      loadedScene.traverse((object) => {
        if (!object.isMesh) return;
        object.castShadow = true;
        object.receiveShadow = true;
      });
      meshGroup.add(loadedScene);
    }).catch(() => {});
  };

  loadAsset();

  const primitiveList = config.cinematicPrimitives || [];
  for (const primitive of primitiveList) {
    const primitiveFn = ctx.primitives?.[primitive.name];
    if (typeof primitiveFn !== 'function') continue;

    const result = primitiveFn(root, primitive.params || {});
    if (result) {
      primitiveResults.push(result);
      if (result.timeline) timelines.push(result.timeline);
    }
  }

  const riseIn = gsap.timeline({ paused: true });
  riseIn.fromTo(
    cardGroup.position,
    { y: -0.15 },
    { y: 0, duration: 0.5, ease: 'power3.out' }
  );
  timelines.push(riseIn);

  const press = gsap.timeline({ paused: true });
  press.to(cardGroup.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'power2.out'
  }).to(cardGroup.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.28,
    ease: 'back.out(2)'
  });
  timelines.push(press);

  const focusTimeline = gsap.timeline({ paused: true });
  focusTimeline.to(edge.scale, {
    x: 1.04,
    duration: 0.3,
    ease: 'power2.out'
  });
  timelines.push(focusTimeline);

  root.userData.handlers = root.userData.handlers || {};

  root.userData.handlers.hover = () => {
    if (disposed) return;
    riseIn.restart();
  };

  root.userData.handlers.click = () => {
    if (disposed) return;
    press.restart();
    ctx.emit?.('hub-home.select', {
      node: root.name,
      source: 'stat-tile'
    });
  };

  root.userData.handlers.focus = () => {
    if (disposed) return;
    focusTimeline.restart();
  };

  root.userData.handlers.blur = () => {
    if (disposed) return;
    focusTimeline.reverse();
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const result of primitiveResults) {
      result?.cleanup?.();
    }

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();

      const material = object.material;
      if (Array.isArray(material)) {
        for (const item of material) item?.dispose?.();
      } else {
        material?.dispose?.();
      }
    });

    for (const resource of disposables) {
      resource?.dispose?.();
    }

    if (loadedScene?.parent) loadedScene.parent.remove(loadedScene);
    root.clear();
  };

  return root;
}
